/**
 * Issue business rules: authorization, per-project issue quota, numbering, status transitions and the events every other concern reacts to.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, wouldExceedLimit, assertNotArchived
 */
import { wouldExceedLimit } from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import {
  actorEnvelope,
  issueResource,
  orgResource,
  projectResource,
  requireFound,
} from "./_support";
import type {
  AssignIssueInput,
  ChangeIssueStatusInput,
  CreateIssueInput,
  IssueFilterInput,
  MoveIssueInput,
  UpdateIssueInput,
} from "@/schemas/issue";
import type { IssueId, OrgId, Page, ProjectId } from "@/types/common";
import type { Issue, IssueBoardColumn, IssueWithRelations } from "@/types/issue";
import type { Actor } from "@/types/member";

/**
 * Creates an issue after four gates: tenant scope, the `issue:create`
 * permission, a live parent project and the plan's per-project issue quota.
 * Only then is a number allocated and `issue.created` published — everything
 * reactive (notifications, search, webhooks, the audit log) hangs off that.
 */
export async function createIssue(
  actor: Actor,
  input: CreateIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const number = await issueRepo.nextIssueNumber(input.orgId, input.projectId);
  const issue = await issueRepo.insertIssue(input, actor.userId, number);

  await emit("issue.created", {
    ...actorEnvelope(actor),
    issueId: issue.id,
    projectId: issue.projectId,
    title: issue.title,
    assigneeId: issue.assigneeId,
    priority: issue.priority,
  });

  return issue;
}

export async function updateIssue(
  actor: Actor,
  input: UpdateIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  const after = await issueRepo.updateIssue(input);

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: Object.keys(input).filter(
      (key) => key !== "orgId" && key !== "issueId",
    ),
  });

  return after;
}

/** Status transitions are an `issue:update`, not a separate permission. */
export async function changeIssueStatus(
  actor: Actor,
  input: ChangeIssueStatusInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  if (before.status === input.status) return before;

  const after = await issueRepo.setIssueStatus(
    input.orgId,
    input.issueId,
    input.status,
  );

  await emit("issue.status_changed", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    from: before.status,
    to: after.status,
  });

  return after;
}

/**
 * Assignment has its own permission because a member may reassign work they
 * do not otherwise own. Un-assigning publishes `issue.updated` instead, since
 * `issue.assigned` carries a non-null assignee by contract.
 */
export async function assignIssue(
  actor: Actor,
  input: AssignIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:assign", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  const after = await issueRepo.setIssueAssignee(
    input.orgId,
    input.issueId,
    input.assigneeId,
  );

  if (input.assigneeId === null) {
    await emit("issue.updated", {
      ...actorEnvelope(actor),
      issueId: after.id,
      projectId: after.projectId,
      changedFields: ["assigneeId"],
    });
    return after;
  }

  await emit("issue.assigned", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    previousAssigneeId: before.assigneeId,
    assigneeId: input.assigneeId,
  });

  return after;
}

export async function archiveIssue(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:archive", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  const archived = await issueRepo.archiveIssue(orgId, issueId);

  await emit("issue.archived", {
    ...actorEnvelope(actor),
    issueId: archived.id,
    projectId: archived.projectId,
  });

  return archived;
}

/**
 * Board drag-and-drop. The index is presentation-only — the board renders by
 * `updated_at` — so a move is a status change plus a touch.
 */
export async function moveIssue(
  actor: Actor,
  input: MoveIssueInput,
): Promise<Issue> {
  return changeIssueStatus(actor, {
    orgId: input.orgId,
    issueId: input.issueId,
    status: input.toStatus,
  });
}

export async function getIssue(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueWithRelations> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  const labels = await labelRepo.listLabelsForIssues(orgId, [issue.id]);

  return {
    issue,
    labels: labels[issue.id] ?? [],
    commentCount: await commentRepo.countComments(orgId, issue.id),
    attachmentCount: (await attachmentRepo.listAttachments(orgId, issue.id))
      .length,
  };
}

export async function listIssues(
  actor: Actor,
  input: IssueFilterInput,
): Promise<Page<Issue>> {
  assertOrgScope(actor, input.orgId);
  // A cross-project list is an org-wide read; per-project visibility is
  // enforced when the caller opens an individual issue.
  assertCan(actor, "issue:read", orgResource(input.orgId));
  return issueRepo.listIssues(input);
}

export async function getBoard(
  actor: Actor,
  orgId: OrgId,
  projectId: ProjectId,
): Promise<readonly IssueBoardColumn[]> {
  assertOrgScope(actor, orgId);

  const project = requireFound(
    await projectRepo.findProjectById(orgId, projectId),
    "Project",
    projectId,
  );
  assertCan(actor, "issue:read", projectResource(project));

  return issueRepo.listBoardColumns(orgId, projectId);
}
/**
 * Cross-project "my issues" view.
 *
 * Owner D. Unlike the per-project list this one spans the whole organization,
 * so the repository filter carries no `projectId` — only the org scope the
 * actor already implies.
 *
 * Must call (do not reimplement): can
 */

import { notFound } from "next/navigation";
import type { Metadata } from "next";
import { IssueList } from "@/components/domain/issue/issue-list";
import { EmptyState } from "@/components/ui/empty-state";
import { can } from "@/lib/permissions";
import { PENDING_ISSUE_ID, PENDING_PROJECT_ID } from "@/actions/_lib/permission-resources";
import { searchParamsPaginationSchema } from "@/schemas/pagination";
import { getIssue, listIssues } from "@/server/services/issue-service";
import { ISSUE_STATUSES, type IssueStatus, type IssueWithRelations } from "@/types/issue";
import { loadTenantContext } from "../_lib/tenant-context";

type PageParams = { orgSlug: string };

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "My issues",
};

const OPEN_STATUSES: readonly IssueStatus[] = [
  "backlog",
  "todo",
  "in_progress",
  "in_review",
];

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { orgSlug } = await props.params;
  const search = await props.searchParams;

  const { org, actor } = await loadTenantContext(orgSlug);

  const allowed = can(actor, "issue:read", {
    kind: "issue",
    orgId: org.id,
    projectId: PENDING_PROJECT_ID,
    issueId: PENDING_ISSUE_ID,
    authorId: actor.userId,
    assigneeId: actor.userId,
  });
  if (!allowed) {
    notFound();
  }

  const pagination = searchParamsPaginationSchema.parse(search);
  const status = parseStatuses(search.status);

  const page = await listIssues(actor, {
    orgId: org.id,
    assigneeId: actor.userId,
    status: [...status],
    limit: pagination.perPage,
    cursor: pagination.cursor ?? null,
  });

  // `IssueList` wants the relations bundle; fetching them one by one is fine at
  // page size, and keeps the list query itself cheap.
  const rows: IssueWithRelations[] = await Promise.all(
    page.items.map((issue) => getIssue(actor, org.id, issue.id)),
  );

  return (
    <div className="space-y-8">
      <header>
        <h1 className="text-2xl font-semibold tracking-tight">My issues</h1>
        <p className="mt-1 text-sm text-slate-600">
          Issues assigned to you across every project in {org.name}.
        </p>
      </header>

      {rows.length === 0 ? (
        <EmptyState
          title="No issues assigned to you"
          description="When somebody assigns you an issue it lands here."
        />
      ) : (
        <IssueList issues={rows} actor={actor} />
      )}
    </div>
  );
}

/** `?status=todo&status=in_progress` narrows the list; anything else is open. */
function parseStatuses(
  raw: string | string[] | undefined,
): readonly IssueStatus[] {
  const values = Array.isArray(raw) ? raw : raw === undefined ? [] : [raw];
  const known = values.filter((value): value is IssueStatus =>
    (ISSUE_STATUSES as readonly string[]).includes(value),
  );
  return known.length > 0 ? known : OPEN_STATUSES;
}
/**
 * Project issue list; parses filters from `await searchParams`.
 *
 * Owner D. The filter is rebuilt from the URL on every render rather than kept
 * in component state, so a filtered list is a shareable link.
 *
 * Must call (do not reimplement): can
 */

import Link from "next/link";
import { notFound } from "next/navigation";
import type { Metadata } from "next";
import { PENDING_ISSUE_ID } from "@/actions/_lib/permission-resources";
import { IssueList } from "@/components/domain/issue/issue-list";
import { EmptyState } from "@/components/ui/empty-state";
import { can } from "@/lib/permissions";
import { issueFilterSchema } from "@/schemas/issue";
import { searchParamsPaginationSchema } from "@/schemas/pagination";
import { getIssue, listIssues } from "@/server/services/issue-service";
import { ISSUE_STATUSES, type IssueStatus, type IssueWithRelations } from "@/types/issue";
import { loadProjectContext } from "../../../_lib/project-context";

type PageParams = { orgSlug: string; projectSlug: string };

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Issues",
};

export default async function Page(props: {
  params: Promise<PageParams>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  // Next.js 16: params and searchParams are Promises and MUST be awaited.
  const { orgSlug, projectSlug } = await props.params;
  const search = await props.searchParams;

  const { org, actor, project } = await loadProjectContext(orgSlug, projectSlug);

  const mayRead = can(actor, "issue:read", {
    kind: "issue",
    orgId: org.id,
    projectId: project.id,
    issueId: PENDING_ISSUE_ID,
    authorId: actor.userId,
    assigneeId: actor.userId,
  });
  if (!mayRead) {
    notFound();
  }

  const mayCreate = can(actor, "issue:create", {
    kind: "issue",
    orgId: org.id,
    projectId: project.id,
    issueId: PENDING_ISSUE_ID,
    authorId: actor.userId,
    assigneeId: null,
  });

  const pagination = searchParamsPaginationSchema.parse(search);
  const statuses = parseStatuses(search.status);

  // The filter goes through the shared schema so an unparseable URL is a
  // rejected filter rather than a malformed repository query.
  const filter = issueFilterSchema.parse({
    orgId: org.id,
    projectId: project.id,
    ...(statuses.length > 0 ? { status: statuses } : {}),
    ...(typeof search.q === "string" ? { query: search.q } : {}),
    includeArchived: search.archived === "1",
    limit: pagination.perPage,
    cursor: pagination.cursor ?? null,
  });

  const page = await listIssues(actor, filter);
  const rows: IssueWithRelations[] = await Promise.all(
    page.items.map((issue) => getIssue(actor, org.id, issue.id)),
  );

  return (
    <div className="space-y-6">
      <div className="flex items-baseline justify-between">
        <p className="text-sm text-slate-600">
          {page.total} issues in {project.name}
        </p>
        {mayCreate ? (
          <Link
            href={`/${orgSlug}/projects/${projectSlug}/issues/new`}
            className="rounded-md bg-indigo-600 px-3 py-1.5 text-sm font-medium text-white"
          >
            New issue
          </Link>
        ) : null}
      </div>

      {rows.length === 0 ? (
        <EmptyState
          title="No issues match this filter"
          description="Clear the filter, or file the first issue in this project."
        />
      ) : (
        <IssueList issues={rows} actor={actor} />
      )}
    </div>
  );
}

function parseStatuses(raw: string | string[] | undefined): IssueStatus[] {
  const values = Array.isArray(raw) ? raw : raw === undefined ? [] : [raw];
  return values.filter((value): value is IssueStatus =>
    (ISSUE_STATUSES as readonly string[]).includes(value),
  );
}
/**
 * Declarative navigation tree. Each item names the permission and flag that
 * gate it, which is how the sidebar stays role-aware without ad-hoc
 * conditionals: `visibleNav()` is the only place that decides what a given
 * actor sees, and it decides by calling `can()` and consulting the flag
 * snapshot rather than by branching on `actor.role`.
 */
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import type { FeatureFlagKey, FeatureFlagSnapshot } from "@/types/feature-flag";
import type { Actor } from "@/types/member";
import type { PermissionAction, PermissionResource } from "@/types/permission";

export type NavItem = {
  key: string;
  label: string;
  segment: string;
  icon?: string;
  action?: PermissionAction;
  flag?: FeatureFlagKey;
  children?: readonly NavItem[];
};

export const SIDEBAR_NAV: readonly NavItem[] = [
  {
    key: "overview",
    label: "Overview",
    segment: "",
    icon: "home",
    action: "org:read",
  },
  {
    key: "projects",
    label: "Projects",
    segment: "projects",
    icon: "folder",
    action: "project:read",
  },
  {
    key: "issues",
    label: "Issues",
    segment: "issues",
    icon: "circle-dot",
    action: "issue:read",
    children: [
      {
        key: "issues.assigned",
        label: "Assigned to me",
        segment: "issues?assignee=me",
        action: "issue:read",
      },
      {
        key: "issues.board",
        label: "Board",
        segment: "board",
        action: "issue:read",
        flag: "kanban_board",
      },
      {
        key: "issues.search",
        label: "Advanced search",
        segment: "search",
        action: "issue:read",
        flag: "advanced_search",
      },
    ],
  },
  {
    key: "inbox",
    label: "Inbox",
    segment: "inbox",
    icon: "bell",
    action: "notification:read",
  },
  {
    key: "activity",
    label: "Activity",
    segment: "activity",
    icon: "history",
    action: "activity:read",
    flag: "activity_feed",
  },
  {
    key: "members",
    label: "Members",
    segment: "members",
    icon: "users",
    action: "member:read",
  },
];

export const SETTINGS_NAV: readonly NavItem[] = [
  {
    key: "settings.general",
    label: "General",
    segment: "general",
    action: "org:read",
  },
  {
    key: "settings.members",
    label: "Members",
    segment: "members",
    action: "member:read",
  },
  {
    key: "settings.billing",
    label: "Billing",
    segment: "billing",
    action: "org:manage_billing",
  },
  {
    key: "settings.flags",
    label: "Feature flags",
    segment: "flags",
    action: "org:manage_flags",
  },
  {
    key: "settings.webhooks",
    label: "Webhooks",
    segment: "webhooks",
    action: "webhook:manage",
    flag: "webhooks",
  },
  {
    key: "settings.export",
    label: "Export",
    segment: "export",
    action: "activity:export",
    flag: "csv_export",
  },
];

/**
 * The resource a nav-level permission question is asked about. Nav items are
 * asked "could this actor do this at all in this org?", so the resource is
 * always the actor's own org, shaped for the action's resource kind.
 */
function navResource(action: PermissionAction, actor: Actor): PermissionResource {
  const [domain] = action.split(":");
  switch (domain) {
    case "org":
      return action === "org:manage_billing"
        ? { kind: "billing", orgId: actor.orgId }
        : { kind: "organization", orgId: actor.orgId };
    case "activity":
      return { kind: "activity", orgId: actor.orgId };
    case "notification":
      return { kind: "notification", orgId: actor.orgId, recipientId: actor.userId };
    case "webhook":
      return { kind: "webhook", orgId: actor.orgId, webhookId: null };
    default:
      // member / project / issue / comment nav entries are org-wide questions.
      return { kind: "organization", orgId: actor.orgId };
  }
}

/**
 * A snapshot is normally complete, but a client provider may be holding one
 * serialised before a flag existed. Fall back to evaluating the flag directly
 * with the conservative context we can build from the actor alone.
 */
function flagAllows(
  flag: FeatureFlagKey,
  actor: Actor,
  flags: FeatureFlagSnapshot,
): boolean {
  const snapshotted: boolean | undefined = flags[flag];
  if (typeof snapshotted === "boolean") return snapshotted;
  return isEnabled(flag, {
    orgId: actor.orgId,
    userId: actor.userId,
    plan: "free",
    role: actor.role,
  });
}

/**
 * Filters a nav tree down to what `actor` may see, recursing into children.
 * A parent whose every child was filtered away and which has no destination
 * of its own is dropped too, so the sidebar never renders an empty group.
 */
export function visibleNav(
  items: readonly NavItem[],
  actor: Actor,
  flags: FeatureFlagSnapshot,
): readonly NavItem[] {
  const visible: NavItem[] = [];

  for (const item of items) {
    if (item.flag !== undefined && !flagAllows(item.flag, actor, flags)) {
      continue;
    }
    if (item.action !== undefined && !can(actor, item.action, navResource(item.action, actor))) {
      continue;
    }

    if (item.children === undefined) {
      visible.push(item);
      continue;
    }

    const children = visibleNav(item.children, actor, flags);
    if (children.length === 0 && item.segment === "") continue;
    visible.push({ ...item, children });
  }

  return visible;
}
